import{$ as e,At as t,H as n,_t as r,at as i,it as a,nt as o,rt as s,xt as c}from"./chunks/framework.ByJSXnli.js";var l=JSON.parse(`{"title":"Layering","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/architecture/layering.md","filePath":"contributing/architecture/layering.md"}`),u={name:`contributing/architecture/layering.md`};function d(n,l,u,d,f,p){let m=c(`LayerStack`);return r(),o(`div`,null,[l[1]||=e(`h1`,{id:`layering`,tabindex:`-1`},[a(`Layering `),e(`a`,{class:`header-anchor`,href:`#layering`,"aria-label":`Permalink to “Layering”`},`​`)],-1),l[2]||=e(`p`,null,`HeuristicLib organizes dependencies by responsibility. A higher layer may use a lower layer. Lower-layer implementations must not take on higher-layer responsibilities. Types in the same layer may collaborate. Folders and assemblies help readers find code, but neither defines a type's layer. The architecture test checks these rules against source references.`,-1),l[3]||=e(`h2`,{id:`layers-and-ownership`,tabindex:`-1`},[a(`Layers and ownership `),e(`a`,{class:`header-anchor`,href:`#layers-and-ownership`,"aria-label":`Permalink to “Layers and ownership”`},`​`)],-1),i(m,null,{default:t(()=>[...l[0]||=[e(`p`,null,`A higher layer may use a lower one, never the reverse. Types in one layer may collaborate. The table lists the full contents of each layer.`,-1)]]),_:1}),l[4]||=s(`<div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Layer</th><th>Responsibility</th><th>Types and concepts</th></tr></thead><tbody><tr><td>L0: domain vocabulary</td><td>Values and concepts independent of configured execution graphs.</td><td>Search spaces, candidate invariants, objectives, randomness, collections and numerics. Problem contracts and representation-independent problem bases. Shared execution concurrency helpers.</td></tr><tr><td>L1: composition model</td><td>Contracts and authoring bases for configurations and executors.</td><td><code>IConfigurationNode</code>, <code>IExecutionNode</code>, <code>IExecutor</code>, <code>IAdaptation</code> and <code>Adaptation&lt;TAdapted&gt;</code> (in <code>Operators</code>, grouped in the <code>Operators/Adaptation</code> folder), <code>ExecutionSignature</code>, validation, role interfaces and authoring bases, including wrapper bases and <code>INamedConfiguration</code>. Operator contract composition and verification.</td></tr><tr><td>L2: resolution</td><td>Managing run-bound results and constructing executor graphs.</td><td><code>ResolutionScope</code>, <code>RunResults</code>, <code>ISubstitution</code>, <code>Substitution</code> and <code>SubstitutionGroup</code> in <code>Execution</code>.</td></tr><tr><td>L3: library content</td><td>Concrete behavior and predefined inspection.</td><td>Scale and offset adaptation configurations and runtime objects in <code>Operators/Adaptation</code>. Instantiable algorithm and operator configurations, encodings and concrete problems. Operation observation records and sources beside each operation. Algorithm observation, <code>ObservationSource&lt;TObservation&gt;</code>, <code>IObservationReceiver&lt;T&gt;</code>, <code>Observing</code>, counters, durations, counting and timing wrappers, clock configurations (<code>CounterClock</code>, <code>DurationClock</code>, <code>ElapsedClock</code>), their <code>IClockReading</code> run results and factories in <code>Inspection</code>.</td></tr><tr><td>L4: hosting</td><td>Starting and coordinating runs and their lifecycles.</td><td><code>AlgorithmRun</code>, <code>ExecutionStream</code> and <code>RunLifecycleState</code> in <code>Execution/Runs</code>. Experiments, trials, <code>ExperimentRun</code> in <code>Experiments</code>.</td></tr><tr><td>L5: analysis</td><td>Deriving and publishing results from observations.</td><td><code>Analyzer&lt;TResult&gt;</code>, <code>AggregateAnalyzer</code>, traces, ranking, best-so-far and retention in <code>Analysis</code>.</td></tr></tbody></table></div><p><code>Algorithms</code> and <code>Operators</code> contain both composition contracts and concrete content. <code>Execution</code> contains domain concurrency helpers, composition contracts, resolution mechanisms and hosting types. <code>Inspection</code> contains only library content: counters, durations and their accumulators, algorithm observation, observation sources and <code>Observing</code>, clock contracts (<code>IClock</code> and <code>IClock&lt;TTime&gt;</code>), configurations and their <code>IClockReading&lt;TTime&gt;</code> run results, and convenience factories. Classify the named type by its responsibility.</p><p>An encoding is a vertical slice through one representation: candidate, search space, operators and recommendations. All types in <code>Encodings</code> are library content. Domain vocabulary remains independent of concrete representations.</p><p>Construction hooks bridge authoring contracts to resolution. A configuration&#39;s construction hook (<code>CreateExecutor</code> for operators and algorithms, <code>CreateExecutionNode</code> for other nodes) receives a <code>ResolutionScope</code> for children and typed result lookup. Hosting creates an independent root scope for each run. Configurations never own resolution storage or hosting lifecycle.</p><p>Generic operator contracts, operations, the operator wrapper base and the routed-executor base <code>RoutingExecutor&lt;TExecutor&gt;</code>, beside <code>WeightedRouter&lt;TChoice&gt;</code>, live in <code>Operators</code>. <code>OperationInfo</code>, the invocation wrapper contracts and the wrapping-executor base <code>WrappingExecutor&lt;TExecutor, TWrapper&gt;</code> live in <code>Execution</code> as composition machinery. Executors own private mutable fields. The run result table binds result-producing configurations by reference. Inspection owns concrete metrics and observations. Neither resolution nor hosting depends on Analysis.</p><p>Experimental can contain content, hosting or analysis at the corresponding layers and depend on the main library. The main library must not depend on Experimental. PythonInterop is an integration client above both libraries.</p><h2 id="dependency-rules" tabindex="-1">Dependency rules <a class="header-anchor" href="#dependency-rules" aria-label="Permalink to “Dependency rules”">​</a></h2><ul><li>Domain vocabulary references only domain vocabulary.</li><li>Hosting may depend on domain vocabulary, composition contracts and resolution. It must not reference <code>Analysis</code> or concrete library algorithms.</li><li>Operators, algorithms, encodings and problems may use lower-layer contracts and shared helpers. Neither their content nor <code>Inspection</code> and resolution may reference <code>Analysis</code>. Observation sources and <code>Observing</code> in <code>Inspection</code> are available to content, such as a meta-algorithm that tracks its contenders.</li><li>Analysis may use content and hosting conveniences. Analysis implements result-producing configuration nodes through the composition contracts. Inspection owns the observation interface and callback groups, so neither content nor resolution needs an Analysis dependency.</li></ul><h2 id="layers-and-execution-phases" tabindex="-1">Layers and execution phases <a class="header-anchor" href="#layers-and-execution-phases" aria-label="Permalink to “Layers and execution phases”">​</a></h2><p>Configuration and executor are phases within these responsibilities. Configurations describe reusable settings, children and analyzers. Executors hold mutable fields and resolved children. <a href="/contributing/architecture/execution-nodes.html">Execution nodes</a> defines what each phase owns. Substitutions rewrite a configuration before resolution, and <code>CreateRun</code> can place a list of them for one run before validation (<a href="/contributing/architecture/execution-resolution.html#substitution-and-ordering">Substitution and ordering</a>).</p><h2 id="run-ownership" tabindex="-1">Run ownership <a class="header-anchor" href="#run-ownership" aria-label="Permalink to “Run ownership”">​</a></h2><p><code>AlgorithmRun</code>, <code>ExecutionStream</code> and <code>RunLifecycleState</code> belong to the <code>HEAL.HeuristicLib.Execution</code> namespace, with their source files grouped under <code>Execution/Runs</code>. Experiment runs remain in <code>HEAL.HeuristicLib.Experiments</code> and share <code>RunLifecycleState</code>.</p><p>Create each run from its configured algorithm. There is no separate setup or supply phase. <code>AlgorithmRun</code> owns its lifecycle and retained execution enumerator together. It is returned in <code>Ready</code>, resolves its executor graph on first start and retains that graph and its iterator across pauses: a paused run retains the enumerator for resumption, and a running stream has exclusive access to it. Completion or failure is terminal, and results remain readable. See <a href="/guide/execution/running-algorithms.html">running algorithms</a> for the lifecycle contract.</p><p><code>ExecutionStream</code> adapts synchronous and asynchronous enumeration and enforces single consumption: each returned stream has one consumer, and a run permits only one active stream. Stream cancellation is cooperative at root-algorithm yield boundaries. It pauses the run instead of interrupting a partially executed iteration.</p><p><code>ExperimentRun</code> owns trial scheduling and its terminal lifecycle. It rejects starting an experiment whose trial has already been started directly.</p><p>The runs share lifecycle state names but have different transition rules. Keep those rules and diagnostics with the run that owns the execution or scheduling. Extract a shared component only when it can own a concrete shared responsibility. Grouping composition fields or moving state transitions behind a configurable host does not establish one.</p><h2 id="concept-placement" tabindex="-1">Concept placement <a class="header-anchor" href="#concept-placement" aria-label="Permalink to “Concept placement”">​</a></h2><p>Namespaces group concepts that users work with together, even when their types belong to different layers. <code>SearchSpaces</code> keeps <code>IOperatorContract</code> beside its composition, verification and compatibility helpers. <code>Data</code> serves symbolic expression interpretation, machine learning and Python integration, so it remains independent of <code>MachineLearning</code>. <code>Collections</code> remains the home of shared collection vocabulary even with a single public type.</p><p>The main benchmark functions share <code>Problems.TestFunctions</code>. <code>SingleObjectives</code>, <code>ZDT</code> and <code>MetaFunctions</code> are grouping folders. Experimental&#39;s <code>Problems.TestFunctions.BBoB</code> is a distinct benchmark suite with different implementations, including types whose names overlap the main functions. Python integration uses the single <code>HEAL.HeuristicLib.PythonInterop</code> namespace with <code>SymbolicRegression</code>, <code>Experiments</code> and <code>Analysis</code> grouping folders. These follow the <a href="/contributing/developer-guidelines.html#§-9-5-match-namespaces-and-folders-by-audience">namespace and folder rules</a>.</p>`,19)])}var f=n(u,[[`render`,d]]);export{l as __pageData,f as default};